def fc_search(query, limit=5):
    resp = mcp_call(FC_MCP, "firecrawl_search", {"query": query, "limit": limit, "lang": "zh"})
    articles = []

    def extract_pages(obj, _depth=0):
        if _depth > 10:
            return []
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict):
            if 'data' in obj and isinstance(obj['data'], list):
                return obj['data']
            content = obj.get('content', [])
            if content and isinstance(content, list):
                try:
                    inner = json.loads(content[0].get('text', '{}'))
                    return extract_pages(inner, _depth + 1)
                except:
                    pass
            result = obj.get('result', {})
            if isinstance(result, dict):
                return extract_pages(result, _depth + 1)
        return []

    pages = extract_pages(resp)
    for p in pages[:limit]:
        if isinstance(p, dict):
            articles.append({
                "title": (p.get('title', '') or '').replace('\\', ''),
                "snippet": (p.get('description', '') or '')[:200],
