def do_scrape(url, fallback_search_cn, brand_name):
    result = {"status": "failed", "url": url, "models": [], "error": ""}

    def fallback_search():
        """双语回退搜索：先中文，空则英文，从搜索结果中提取型号"""
        if fallback_search_cn:
            articles = bocha_search(fallback_search_cn, 5)
            if articles:
                return articles
        articles = bocha_search(f"{brand_name} refrigerator 2026 new models", 5)
        return articles

    if not url:
        articles = fallback_search()
        if articles:
            models = extract_models_from_articles(articles)
            return {"status": "fallback", "models": models, "model_count": len(models), "articles": articles}
        result["error"] = "无可用官网URL"
        return result

    try:
        md = fc_scrape(url)
        if not md:
            articles = fallback_search()
            if articles:
                models = extract_models_from_articles(articles)
                return {"status": "fallback", "models": models, "model_count": len(models), "articles": articles}
            result["error"] = "官网抓取失败：无内容返回"
            return result

        if is_blocked(md):
            articles = fallback_search()
            if articles:
                models = extract_models_from_articles(articles)
                return {"status": "fallback", "models": models, "model_count": len(models), "articles": articles}
            result["error"] = "官网被反爬拦截"
            return result

        models = extract_from_md(md)
        if models:
            result["status"] = "success"
            result["models"] = models
            result["model_count"] = len(models)
        else:
            result["status"] = "partial"
            result["error"] = "页面抓取成功但未提取到产品"
            result["markdown_preview"] = md[:800]

        return result

    except Exception as e:
        result["error"] = str(e)[:200]
        articles = fallback_search()
        if articles:
            models = extract_models_from_articles(articles)
            return {"status": "fallback", "models": models, "model_count": len(models), "articles": articles}
        return result


def do_ecommerce(url, fallback_search_cn, brand_name):
    result = {"status": "failed", "url": url, "products": [], "error": ""}

    def fallback_search():
        if fallback_search_cn:
            articles = bocha_search(fallback_search_cn, 5)
            if articles:
                return articles
        articles = bocha_search(f"{brand_name} refrigerator 2026", 5)
        return articles

    if not url:
